let diagram;
let normal;
let cells = [];
let sniffed = [];
let colours = ["#f8e3c4", "#cc3495", "#6b1fb1", "#0b0630"]
let palette;

function fillPattern(type) {
  palette = shuffle(colours, true);
    palette = palette.slice(0, 3);
    patternColors(shuffle(palette));
  if (type === "ptn") {
    let ptArr = [
      // PTN.stripeCircle(int(random(7, 12))),
      PTN.stripePolygon(random([3, 5, 6]), int(random(10, 50))),
      // PTN.stripeRadial(360 / random([30, 60, 90])),
      // PTN.wave(int(random(1, 3)), int(random(10, 20)), 5, 10),
      // PTN.dot(10, 10 * random(0.5, 1))
    ]
    return random(ptArr);
  } else {
    var ptArr = [
      PTN.noiseGrad(0.9),
      PTN.noiseGrad(0.3),
      PTN.noiseGrad(0.2)
    ]
    return random(ptArr);
  }
}

function setup() {
  createCanvas(600, 600);
  angleMode(DEGREES);
  voronoiCellStrokeWeight(3);
  voronoiCellStroke("#0b0630");
  voronoiRndSites(20, 100);
  voronoiSiteFlag(false);
  voronoi(600, 600, true);
  diagram = voronoiGetDiagram(); //this gives you lots of info
  normal = voronoiGetCells(); //this gives you the vertices of the cells

  // getting the locations of the seeds/sites... but I didn't use them
  for (let i = 0; i < diagram.cells.length; i++) {
    let x = diagram.cells[i].site.x;
    let y = diagram.cells[i].site.y;
    cells.push({ x: x, y: y });
    sniffed.push(false);
  }
}

function draw() {
	background(colours[3])
  // noLoop() removed for animation
  for (let i = 0; i < normal.length; i++) {
    pattern(fillPattern("noise"));
    beginShapePattern();
    for (let j = 0; j < normal[i].length; j++) {
      vertexPattern(normal[i][j][0], normal[i][j][1]);
    }
    endShapePattern(CLOSE);
  }
  // voronoiDraw(0, 0, false, false);
}

let prevCell;
function mouseMoved() {
  let cellId = voronoiGetSite((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), false);
  if (cellId === undefined) {
    prevCell = undefined;
  } else if (cellId !== prevCell) {
    sniffed[cellId] = !sniffed[cellId];
    let pts = normal[cellId];
    palette = shuffle(colours, true);
    palette = palette.slice(0, 3);
    patternColors(shuffle(palette));
    if (!sniffed[cellId]) {
      pattern(fillPattern("noise"));
    } else {
      pattern(fillPattern("ptn"));
    }
    beginShapePattern();
    for (let i = 0; i < pts.length; i++) {
      vertexPattern(pts[i][0], pts[i][1]);
    }
    endShapePattern(CLOSE);
    // console.log(cellId)
    prevCell = cellId;
  }
}
